def stored_cap(db):
    import sqlite3
    with contextlib.closing(sqlite3.connect(Path(db).resolve().as_uri() + "?mode=ro", uri=True)) as conn:
        return conn.execute("SELECT global_cap FROM meta WHERE id=1").fetchone()[0]


